acceptance_cmd:
set -x; export KG_GROUPS="$(./ops/test_ops.sh --list 2>/dev/null)"; ./ops/ui_quality_plane.py validate >/dev/null || exit 2; ./ops/ui_quality_plane.py list --json 2>/dev/null | uv run --no-project --python 3.13 python -c '
import json, os, subprocess, sys
from pathlib import Path
GATES = {"ci", "test_ops", "ios-test", "xcode", "manual"}
ENTRY = "ios/BooksAndVocabTests/ReviewCardLayoutGoldenTests.swift"
GOLD = "ios/BooksAndVocabTests/Golden/review_card_layout.json"
NEG = "ops/tests/test_review_card_layout_golden.sh"
GROUP = "review-card-golden"
PROFILE = "ios/BooksAndVocab/Models/ReviewCardLayoutProfile.swift"
VIEWS = "ios/BooksAndVocab/Views/Vocabulary/"
def posctrl(msg):
    print("POSCTRL-FAIL:", msg); sys.exit(2)
if not Path("ops/ui_quality_plane.yml").is_file(): posctrl("not at repo root")
if subprocess.run(["git", "rev-parse", "--is-inside-work-tree"], capture_output=True).returncode != 0: posctrl("git unavailable, the tracked-file clause cannot be judged")
try:
    ms = json.load(sys.stdin)
except Exception as exc:
    posctrl("ui_quality_plane list unreadable: %s" % exc)
if len(ms) < 14: posctrl("mechanism list too short: %d" % len(ms))
i18n = [m for m in ms if m.get("id") == "static.i18n"]
if not i18n or i18n[0].get("gate") not in GATES: posctrl("known mechanism static.i18n missing or its gate did not parse")
groups = set(os.environ.get("KG_GROUPS", "").split())
if "ui-quality-plane" not in groups: posctrl("test_ops.sh --list unreadable")
def tracked(p):
    return subprocess.run(["git", "ls-files", "--error-unmatch", p], capture_output=True).returncode == 0
gaps = []
hits = [m for m in ms if m.get("gate") == "ios-test" and m.get("entrypoint") == ENTRY and any(t.startswith(VIEWS) for t in m.get("triggers") or []) and PROFILE in (m.get("triggers") or []) and m.get("regression") == GROUP]
if not hits: gaps.append("no ios-test mechanism with entrypoint=" + ENTRY + ", triggers covering both " + VIEWS + " and " + PROFILE + ", regression=" + GROUP)
if GROUP not in groups: gaps.append("group " + GROUP + " not listed by test_ops.sh --list")
for p in (ENTRY, GOLD, NEG):
    if not Path(p).is_file(): gaps.append("absent: " + p)
    elif not tracked(p): gaps.append("not in the git index, git add it: " + p)
if Path(GOLD).is_file():
    try:
        blob = json.dumps(json.loads(Path(GOLD).read_text(encoding="utf-8"))).lower()
    except Exception as exc:
        gaps.append("golden is not JSON: %s" % exc)
    else:
        for tok in ("recognition", "production", "front", "back", "prompt", "answer", "answerdivider", "difficultytier"):
            if tok not in blob: gaps.append("golden never mentions " + tok)
if Path(ENTRY).is_file() and "review_card_layout" not in Path(ENTRY).read_text(encoding="utf-8"): gaps.append("the test never reads " + GOLD)
if Path(NEG).is_file() and not os.access(NEG, os.X_OK): gaps.append("not executable: " + NEG)
if gaps:
    print("review-card layout guard NOT enforced:")
    for g in gaps: print("  -", g)
    sys.exit(1)
print("enforced review-card layout guard:", [m["id"] for m in hits]); sys.exit(0)
'
